-- Generado por scripts/generate-supabase-sql.mjs. No editar a mano.
-- Pegar completo en Supabase → SQL Editor → Run. Se puede ejecutar varias veces.

create table if not exists public.languages (
  id text primary key,
  name text not null,
  tagline text not null,
  color text not null,
  year int not null,
  founders text[] not null default '{}',
  paradigm text not null,
  history text not null,
  key_features text[] not null default '{}',
  curiosity text not null,
  use_cases text[] not null default '{}',
  variables_example jsonb,
  conditionals_example jsonb,
  loops_example jsonb,
  steps jsonb not null default '[]',
  courses jsonb not null default '[]'
);

create table if not exists public.frameworks (
  id text primary key,
  name text not null,
  language_id text not null references public.languages(id) on delete cascade,
  tagline text not null,
  description text not null,
  year int not null,
  creator text not null,
  color text not null,
  key_features text[] not null default '{}',
  curiosity text not null,
  use_cases text[] not null default '{}',
  docs_url text not null
);

create index if not exists idx_frameworks_language on public.frameworks(language_id);

-- Row Level Security: solo usuarios autenticados (con token válido) pueden leer.
-- Nadie puede escribir desde la API pública; los datos se administran desde el panel.
grant select on public.languages, public.frameworks to authenticated;

alter table public.languages enable row level security;
alter table public.frameworks enable row level security;

drop policy if exists "Autenticados leen lenguajes" on public.languages;
create policy "Autenticados leen lenguajes" on public.languages
  for select to authenticated using (true);

drop policy if exists "Autenticados leen frameworks" on public.frameworks;
create policy "Autenticados leen frameworks" on public.frameworks
  for select to authenticated using (true);

insert into public.languages (id, name, tagline, color, year, founders, paradigm, history, key_features, curiosity, use_cases, variables_example, conditionals_example, loops_example, steps, courses) values
  ('javascript', 'JavaScript', 'El idioma de la Web', '#F0DB4F', 1995, array['Brendan Eich']::text[], 'Multiparadigma: orientado a objetos, funcional y basado en eventos', 'En 1995, Netscape necesitaba un lenguaje de scripting para sus navegadores y le encargó la tarea a Brendan Eich, quien lo diseñó en tan solo 10 días. Al principio se llamó Mocha, luego LiveScript, y finalmente JavaScript por motivos de marketing, aprovechando la popularidad de Java. Hoy es el lenguaje más usado del planeta y corre en prácticamente todos los navegadores.', array['Tipado dinámico y flexible', 'Se ejecuta en el navegador y en el servidor (Node.js)', 'Programación asíncrona con Promises y async/await', 'El ecosistema de paquetes más grande del mundo (npm)']::text[], 'A pesar de compartir parte del nombre, JavaScript no tiene ninguna relación técnica con Java. El nombre fue una decisión de marketing de Netscape para aprovechar la popularidad de Java en 1995.', array['Desarrollo web frontend', 'Aplicaciones móviles con React Native', 'Servidores con Node.js', 'Videojuegos en el navegador']::text[], '{"description":"Usa let para variables que pueden cambiar y const para valores que no cambian.","code":"let edad = 18;\nconst nombre = \"Ana\";\nlet activo = true;"}'::jsonb, '{"description":"if/else evalúa una condición y ejecuta un bloque u otro según el resultado.","code":"let edad = 18;\n\nif (edad >= 18) {\n  console.log(\"Eres mayor de edad\");\n} else {\n  console.log(\"Eres menor de edad\");\n}"}'::jsonb, '{"description":"El bucle for repite un bloque de código un número determinado de veces.","code":"for (let i = 0; i < 5; i++) {\n  console.log(\"Vuelta número \" + i);\n}"}'::jsonb, '[{"title":"Prepara tu entorno","description":"Instala Node.js desde nodejs.org para poder ejecutar JavaScript fuera del navegador."},{"title":"Crea tu archivo","description":"Crea un archivo llamado hola.js en cualquier carpeta de tu computadora."},{"title":"Escribe tu primer programa","description":"Declara una variable y muestra un saludo en la consola.","code":"let nombre = \"Mundo\";\nconsole.log(\"¡Hola, \" + nombre + \"!\");"},{"title":"Ejecútalo","description":"Abre una terminal en esa carpeta y escribe el siguiente comando. Verás el mensaje al instante.","code":"node hola.js"}]'::jsonb, '[{"title":"Documentación oficial","platform":"MDN Web Docs","url":"https://developer.mozilla.org/es/docs/Web/JavaScript"},{"title":"Cursos gratuitos","platform":"freeCodeCamp","url":"https://www.freecodecamp.org/learn"}]'::jsonb),
  ('python', 'Python', 'Simplicidad y legibilidad ante todo', '#3776AB', 1991, array['Guido van Rossum']::text[], 'Multiparadigma: imperativo, orientado a objetos y funcional', 'Guido van Rossum comenzó a desarrollar Python a finales de 1989 como un proyecto personal para las fiestas navideñas, y lo lanzó oficialmente en 1991. Le puso ese nombre en honor al grupo de comedia británico Monty Python, no a la serpiente. Su filosofía prioriza la legibilidad del código, resumida en un texto conocido como el "Zen de Python".', array['Sintaxis clara que se lee casi como inglés', 'Tipado dinámico con tipado opcional (type hints)', 'Enorme cantidad de librerías para ciencia de datos e IA', 'Multiplataforma: Windows, macOS y Linux']::text[], 'Guido van Rossum fue reconocido por la comunidad Python como el "Dictador Benevolente Vitalicio" (BDFL), un título honorífico que tuvo hasta que renunció a él en 2018.', array['Ciencia de datos e inteligencia artificial', 'Automatización y scripts', 'Desarrollo web con Django o Flask', 'Educación para quienes empiezan a programar']::text[], '{"description":"En Python no se declara el tipo: simplemente asignas un valor a un nombre.","code":"edad = 18\nnombre = \"Ana\"\nactivo = True"}'::jsonb, '{"description":"Los bloques en Python se definen con indentación, no con llaves.","code":"edad = 18\n\nif edad >= 18:\n    print(\"Eres mayor de edad\")\nelse:\n    print(\"Eres menor de edad\")"}'::jsonb, '{"description":"for junto con range() repite un bloque un número determinado de veces.","code":"for i in range(5):\n    print(f\"Vuelta número {i}\")"}'::jsonb, '[{"title":"Instala Python","description":"Descarga Python desde python.org e instálalo en tu computadora."},{"title":"Crea tu archivo","description":"Crea un archivo llamado hola.py"},{"title":"Escribe tu primer programa","description":"Guarda un nombre en una variable e imprímelo con un saludo.","code":"nombre = \"Mundo\"\nprint(f\"¡Hola, {nombre}!\")"},{"title":"Ejecútalo","description":"En la terminal, dentro de la carpeta del archivo, escribe el siguiente comando.","code":"python hola.py"}]'::jsonb, '[{"title":"Tutorial oficial","platform":"python.org","url":"https://docs.python.org/es/3/tutorial/"},{"title":"Cursos gratuitos","platform":"freeCodeCamp","url":"https://www.freecodecamp.org/learn"}]'::jsonb),
  ('java', 'Java', 'Escribe una vez, ejecuta en cualquier lugar', '#EA2D2E', 1995, array['James Gosling']::text[], 'Orientado a objetos', 'James Gosling y su equipo en Sun Microsystems crearon Java a mediados de los años 90 con la promesa de "escribe una vez, ejecuta en cualquier lugar", gracias a la máquina virtual de Java (JVM). Originalmente se llamó Oak, en honor a un árbol que Gosling veía desde su oficina, pero se renombró a Java. Se convirtió en el lenguaje base de Android y de miles de sistemas empresariales.', array['Se ejecuta sobre la máquina virtual de Java (JVM)', 'Tipado estático y fuertemente orientado a objetos', 'Recolector de basura automático', 'Compatibilidad hacia atrás muy sólida entre versiones']::text[], 'El café es el motivo del nombre y del logo: el equipo se inspiró en las tazas de café que tomaban durante las reuniones de diseño del lenguaje.', array['Aplicaciones Android', 'Sistemas empresariales', 'Backend de grandes plataformas', 'Software académico']::text[], '{"description":"En Java toda variable debe declarar explícitamente su tipo.","code":"int edad = 18;\nString nombre = \"Ana\";\nboolean activo = true;"}'::jsonb, '{"description":"if/else evalúa una condición booleana entre paréntesis.","code":"int edad = 18;\n\nif (edad >= 18) {\n  System.out.println(\"Eres mayor de edad\");\n} else {\n  System.out.println(\"Eres menor de edad\");\n}"}'::jsonb, '{"description":"El bucle for clásico repite un bloque un número determinado de veces.","code":"for (int i = 0; i < 5; i++) {\n  System.out.println(\"Vuelta número \" + i);\n}"}'::jsonb, '[{"title":"Instala el JDK","description":"Descarga e instala el Java Development Kit (JDK) en tu computadora."},{"title":"Crea tu archivo","description":"Crea un archivo llamado Hola.java (con mayúscula inicial, igual que la clase)."},{"title":"Escribe tu primer programa","description":"Toda la lógica va dentro de una clase con un método main.","code":"public class Hola {\n  public static void main(String[] args) {\n    String nombre = \"Mundo\";\n    System.out.println(\"¡Hola, \" + nombre + \"!\");\n  }\n}"},{"title":"Compila y ejecuta","description":"Compila el archivo y luego ejecuta la clase generada.","code":"javac Hola.java\njava Hola"}]'::jsonb, '[{"title":"Aprende Java","platform":"dev.java (Oracle)","url":"https://dev.java/learn/"},{"title":"Cursos gratuitos","platform":"freeCodeCamp","url":"https://www.freecodecamp.org/learn"}]'::jsonb),
  ('cpp', 'C++', 'Un paso más allá de C', '#00599C', 1985, array['Bjarne Stroustrup']::text[], 'Multiparadigma: procedural, orientado a objetos y genérico', 'Bjarne Stroustrup comenzó en 1979 a mejorar el lenguaje C agregándole clases, por lo que al inicio lo llamó "C with Classes". En 1983 fue renombrado C++, un juego de palabras con el operador de incremento "++" de C, indicando que era un paso más allá de C. Hoy impulsa videojuegos, sistemas operativos y software que exige el máximo rendimiento.', array['Control de memoria manual y de bajo nivel', 'Programación orientada a objetos y genérica (plantillas)', 'Compatible casi al 100% con el lenguaje C', 'Rendimiento cercano al del hardware']::text[], 'Motores de videojuegos como Unreal Engine están escritos en C++ precisamente por el control tan fino que da sobre la memoria y el rendimiento.', array['Videojuegos y motores gráficos', 'Sistemas operativos', 'Software de alto rendimiento', 'Sistemas embebidos']::text[], '{"description":"En C++ toda variable declara su tipo explícitamente.","code":"int edad = 18;\nstd::string nombre = \"Ana\";\nbool activo = true;"}'::jsonb, '{"description":"if/else evalúa una condición entre paréntesis, igual que en C.","code":"int edad = 18;\n\nif (edad >= 18) {\n  cout << \"Eres mayor de edad\" << endl;\n} else {\n  cout << \"Eres menor de edad\" << endl;\n}"}'::jsonb, '{"description":"El bucle for clásico repite un bloque un número determinado de veces.","code":"for (int i = 0; i < 5; i++) {\n  cout << \"Vuelta número \" << i << endl;\n}"}'::jsonb, '[{"title":"Instala un compilador","description":"Instala g++ (por ejemplo, a través de MinGW en Windows) para poder compilar C++."},{"title":"Crea tu archivo","description":"Crea un archivo llamado hola.cpp"},{"title":"Escribe tu primer programa","description":"Incluye la librería de entrada/salida y usa cout para imprimir en pantalla.","code":"#include <iostream>\nusing namespace std;\n\nint main() {\n  string nombre = \"Mundo\";\n  cout << \"¡Hola, \" << nombre << \"!\" << endl;\n  return 0;\n}"},{"title":"Compila y ejecuta","description":"Compila el archivo para generar un ejecutable y luego corre ese ejecutable.","code":"g++ hola.cpp -o hola\n./hola"}]'::jsonb, '[{"title":"Tutorial interactivo","platform":"cplusplus.com","url":"https://cplusplus.com/doc/tutorial/"},{"title":"Cursos gratuitos","platform":"freeCodeCamp","url":"https://www.freecodecamp.org/learn"}]'::jsonb),
  ('csharp', 'C#', 'La potencia de C++ con sintaxis simple', '#68217A', 2000, array['Anders Hejlsberg']::text[], 'Orientado a objetos', 'Anders Hejlsberg, quien antes había creado Turbo Pascal y Delphi, lideró el diseño de C# en Microsoft a finales de los años 90 como pieza central de la nueva plataforma .NET. Se presentó oficialmente en el año 2000. Combina la potencia de C++ con una sintaxis más simple, y hoy es el lenguaje principal para crear videojuegos con el motor Unity.', array['Tipado estático con inferencia de tipos', 'Recolector de basura automático', 'Integración total con el ecosistema .NET', 'Soporte de primer nivel en el motor de videojuegos Unity']::text[], 'El símbolo "#" en el nombre representa cuatro signos de "+" acomodados en cuadrícula, sugiriendo que C# es una mejora incremental sobre C++.', array['Videojuegos con Unity', 'Aplicaciones de escritorio Windows', 'Backend con ASP.NET', 'Aplicaciones empresariales']::text[], '{"description":"En C# toda variable declara su tipo, aunque también existe var para inferirlo.","code":"int edad = 18;\nstring nombre = \"Ana\";\nbool activo = true;"}'::jsonb, '{"description":"if/else evalúa una condición booleana entre paréntesis.","code":"int edad = 18;\n\nif (edad >= 18) {\n  Console.WriteLine(\"Eres mayor de edad\");\n} else {\n  Console.WriteLine(\"Eres menor de edad\");\n}"}'::jsonb, '{"description":"El bucle for clásico repite un bloque un número determinado de veces.","code":"for (int i = 0; i < 5; i++) {\n  Console.WriteLine(\"Vuelta número \" + i);\n}"}'::jsonb, '[{"title":"Instala el SDK de .NET","description":"Descarga e instala el .NET SDK desde el sitio oficial de Microsoft."},{"title":"Crea un proyecto","description":"Usa la terminal para generar un proyecto de consola nuevo.","code":"dotnet new console -o HolaMundo"},{"title":"Escribe tu primer programa","description":"Abre Program.cs y reemplaza su contenido con lo siguiente.","code":"string nombre = \"Mundo\";\nConsole.WriteLine($\"¡Hola, {nombre}!\");"},{"title":"Ejecútalo","description":"Dentro de la carpeta del proyecto, corre el siguiente comando.","code":"dotnet run"}]'::jsonb, '[{"title":"Tour por C#","platform":"Microsoft Learn","url":"https://learn.microsoft.com/es-es/dotnet/csharp/"},{"title":"Cursos gratuitos","platform":"freeCodeCamp","url":"https://www.freecodecamp.org/learn"}]'::jsonb),
  ('php', 'PHP', 'El motor silencioso de la Web', '#777BB4', 1994, array['Rasmus Lerdorf']::text[], 'Multiparadigma: procedural y orientado a objetos', 'Rasmus Lerdorf creó PHP en 1994 como un conjunto de scripts en C para llevar el conteo de visitas de su página personal; de hecho, PHP significaba originalmente "Personal Home Page". Con el tiempo se transformó en un lenguaje completo para la web, y hoy su acrónimo recursivo es "PHP: Hypertext Preprocessor". Sitios como Facebook y Wikipedia nacieron sobre PHP.', array['Diseñado específicamente para la web', 'Se integra directamente dentro del HTML', 'Enorme comunidad y hosting disponible en casi cualquier proveedor', 'Base de gestores de contenido como WordPress']::text[], 'Una gran parte de todos los sitios web cuyo lenguaje de servidor se puede identificar están construidos con PHP, principalmente gracias a WordPress.', array['Desarrollo web backend', 'Sistemas de gestión de contenido como WordPress', 'Comercio electrónico', 'APIs web']::text[], '{"description":"Las variables en PHP siempre empiezan con el símbolo $.","code":"$edad = 18;\n$nombre = \"Ana\";\n$activo = true;"}'::jsonb, '{"description":"if/else funciona igual que en C, evaluando una condición entre paréntesis.","code":"$edad = 18;\n\nif ($edad >= 18) {\n    echo \"Eres mayor de edad\";\n} else {\n    echo \"Eres menor de edad\";\n}"}'::jsonb, '{"description":"El bucle for clásico repite un bloque un número determinado de veces.","code":"for ($i = 0; $i < 5; $i++) {\n    echo \"Vuelta número \" . $i;\n}"}'::jsonb, '[{"title":"Instala PHP","description":"Instala PHP directamente o usa un entorno como Laragon o XAMPP."},{"title":"Crea tu archivo","description":"Crea un archivo llamado hola.php"},{"title":"Escribe tu primer programa","description":"El código PHP va entre las etiquetas <?php y ?>.","code":"<?php\n$nombre = \"Mundo\";\necho \"¡Hola, \" . $nombre . \"!\";\n?>"},{"title":"Ejecútalo","description":"Corre el archivo con el servidor embebido de PHP desde la terminal.","code":"php hola.php"}]'::jsonb, '[{"title":"Tutorial oficial","platform":"php.net","url":"https://www.php.net/manual/es/tutorial.php"},{"title":"Cursos gratuitos","platform":"freeCodeCamp","url":"https://www.freecodecamp.org/learn"}]'::jsonb),
  ('kotlin', 'Kotlin', 'Moderno, seguro y hecho para Android', '#7F52FF', 2011, array['JetBrains (liderado por Andrey Breslav)']::text[], 'Multiparadigma: orientado a objetos y funcional', 'El equipo de JetBrains presentó Kotlin en 2011, liderado por Andrey Breslav, buscando un lenguaje más moderno y seguro que Java pero compatible con la JVM. Le pusieron el nombre en honor a la isla de Kotlin, cerca de San Petersburgo, siguiendo la tradición de nombrar lenguajes JetBrains como islas rusas. En 2017, Google lo convirtió en lenguaje oficial para desarrollar apps de Android.', array['Interoperabilidad total con Java', 'Sintaxis concisa que reduce el código repetitivo (boilerplate)', 'Seguridad frente a valores nulos (null safety) integrada al lenguaje', 'Lenguaje oficial de Android desde 2019']::text[], 'JetBrains, la empresa detrás de Kotlin, también crea IntelliJ IDEA, el IDE en el que está basado Android Studio.', array['Aplicaciones Android nativas', 'Backend con Kotlin y Spring', 'Aplicaciones multiplataforma (KMP)', 'Scripting']::text[], '{"description":"Usa var para variables que cambian y val para valores que no cambian.","code":"var edad = 18\nval nombre = \"Ana\"\nvar activo = true"}'::jsonb, '{"description":"if/else en Kotlin puede usarse como sentencia o como expresión que devuelve un valor.","code":"val edad = 18\n\nif (edad >= 18) {\n    println(\"Eres mayor de edad\")\n} else {\n    println(\"Eres menor de edad\")\n}"}'::jsonb, '{"description":"for in recorre un rango de valores de forma directa.","code":"for (i in 0 until 5) {\n    println(\"Vuelta número $i\")\n}"}'::jsonb, '[{"title":"Instala Kotlin","description":"Instala el compilador de Kotlin o usa Android Studio, que ya lo incluye."},{"title":"Crea tu archivo","description":"Crea un archivo llamado Hola.kt"},{"title":"Escribe tu primer programa","description":"El punto de entrada es una función main.","code":"fun main() {\n    val nombre = \"Mundo\"\n    println(\"¡Hola, $nombre!\")\n}"},{"title":"Compila y ejecuta","description":"Compila el archivo a un .jar ejecutable y luego corre ese .jar.","code":"kotlinc Hola.kt -include-runtime -d hola.jar\njava -jar hola.jar"}]'::jsonb, '[{"title":"Primeros pasos","platform":"kotlinlang.org","url":"https://kotlinlang.org/docs/getting-started.html"},{"title":"Cursos gratuitos","platform":"freeCodeCamp","url":"https://www.freecodecamp.org/learn"}]'::jsonb),
  ('swift', 'Swift', 'Rápido, seguro y pensado para Apple', '#F05138', 2014, array['Chris Lattner (Apple)']::text[], 'Multiparadigma: orientado a objetos, protocolos y funcional', 'Chris Lattner comenzó a diseñar Swift en Apple en 2010, de forma casi secreta durante varios años, con la meta de reemplazar a Objective-C. Se presentó al público en la conferencia WWDC de 2014 y sorprendió a toda la comunidad de desarrolladores. Fue creado para ser más seguro, rápido y fácil de leer que su predecesor.', array['Seguridad de tipos y manejo seguro de valores nulos (optionals)', 'Muy rápido gracias al compilador LLVM', 'Sintaxis moderna y concisa', 'Código abierto desde 2015']::text[], 'Aunque nació para reemplazar a Objective-C, Apple diseñó Swift para poder convivir con código Objective-C dentro del mismo proyecto durante la transición.', array['Aplicaciones para iPhone y iPad', 'Aplicaciones para Mac', 'Aplicaciones para Apple Watch', 'Software para visionOS']::text[], '{"description":"Usa var para variables que cambian y let para valores que no cambian.","code":"var edad = 18\nlet nombre = \"Ana\"\nvar activo = true"}'::jsonb, '{"description":"if/else en Swift no necesita paréntesis alrededor de la condición.","code":"let edad = 18\n\nif edad >= 18 {\n    print(\"Eres mayor de edad\")\n} else {\n    print(\"Eres menor de edad\")\n}"}'::jsonb, '{"description":"for-in recorre un rango de valores con el operador ..<.","code":"for i in 0..<5 {\n    print(\"Vuelta número \\(i)\")\n}"}'::jsonb, '[{"title":"Instala Xcode","description":"Instala Xcode desde la Mac App Store (requiere una computadora Mac)."},{"title":"Crea tu archivo","description":"Crea un archivo llamado hola.swift"},{"title":"Escribe tu primer programa","description":"Swift permite interpolar variables directamente dentro de los textos.","code":"let nombre = \"Mundo\"\nprint(\"¡Hola, \\(nombre)!\")"},{"title":"Ejecútalo","description":"Desde la terminal, ejecuta el archivo directamente con el intérprete de Swift.","code":"swift hola.swift"}]'::jsonb, '[{"title":"Swift Book","platform":"swift.org","url":"https://docs.swift.org/swift-book/"},{"title":"Cursos gratuitos","platform":"freeCodeCamp","url":"https://www.freecodecamp.org/learn"}]'::jsonb),
  ('go', 'Go', 'Simplicidad y concurrencia a gran escala', '#00ADD8', 2009, array['Robert Griesemer', 'Rob Pike', 'Ken Thompson']::text[], 'Procedural y concurrente', 'En 2007, tres ingenieros de Google —Robert Griesemer, Rob Pike y Ken Thompson, este último cocreador de Unix— se cansaron de la lentitud para compilar proyectos gigantes en C++ y diseñaron Go como respuesta. Se hizo público en 2009 y destaca por su simplicidad y su manejo nativo de la concurrencia mediante las llamadas "goroutines". Hoy es el lenguaje detrás de herramientas como Docker y Kubernetes.', array['Concurrencia sencilla con goroutines y channels', 'Compila a binarios únicos sin dependencias externas', 'Sintaxis minimalista a propósito', 'Recolector de basura con pausas muy cortas']::text[], 'Go también es conocido como "Golang" simplemente porque el dominio go.org ya estaba ocupado cuando se buscó una dirección web para el proyecto.', array['Infraestructura en la nube', 'Microservicios', 'Herramientas de línea de comandos', 'Sistemas concurrentes']::text[], '{"description":"El operador := declara e infiere el tipo de la variable en un solo paso.","code":"edad := 18\nnombre := \"Ana\"\nactivo := true"}'::jsonb, '{"description":"if/else en Go no necesita paréntesis alrededor de la condición.","code":"edad := 18\n\nif edad >= 18 {\n    fmt.Println(\"Eres mayor de edad\")\n} else {\n    fmt.Println(\"Eres menor de edad\")\n}"}'::jsonb, '{"description":"Go solo tiene un tipo de bucle: for, que puede usarse de varias formas.","code":"for i := 0; i < 5; i++ {\n    fmt.Println(\"Vuelta número\", i)\n}"}'::jsonb, '[{"title":"Instala Go","description":"Descarga Go desde go.dev e instálalo en tu computadora."},{"title":"Crea tu archivo","description":"Crea un archivo llamado hola.go"},{"title":"Escribe tu primer programa","description":"Todo programa en Go pertenece a un paquete, generalmente \"main\".","code":"package main\n\nimport \"fmt\"\n\nfunc main() {\n    nombre := \"Mundo\"\n    fmt.Println(\"¡Hola, \" + nombre + \"!\")\n}"},{"title":"Ejecútalo","description":"Corre el archivo directamente con el comando \"go run\".","code":"go run hola.go"}]'::jsonb, '[{"title":"A Tour of Go","platform":"go.dev","url":"https://go.dev/tour/welcome/1"},{"title":"Cursos gratuitos","platform":"freeCodeCamp","url":"https://www.freecodecamp.org/learn"}]'::jsonb),
  ('ruby', 'Ruby', 'Diseñado para la felicidad del programador', '#CC342D', 1995, array['Yukihiro "Matz" Matsumoto']::text[], 'Orientado a objetos', 'El programador japonés Yukihiro Matsumoto, conocido como "Matz", creó Ruby en 1995 buscando un lenguaje que priorizara la felicidad de quien programa por encima de todo. Mezcló ideas de Perl, Smalltalk y Lisp para lograr una sintaxis elegante y natural. Se hizo mundialmente famoso gracias al framework Ruby on Rails, que revolucionó la velocidad del desarrollo web.', array['Todo en Ruby es un objeto, incluso los números', 'Sintaxis expresiva pensada para la felicidad del programador', 'Metaprogramación muy potente', 'Gestor de paquetes propio: RubyGems']::text[], 'La filosofía de Ruby se resume en el "principio de menor sorpresa": el lenguaje debe comportarse como el programador espera, sin sorpresas raras.', array['Desarrollo web con Ruby on Rails', 'Prototipado rápido', 'Automatización de tareas', 'Scripts de administración de sistemas']::text[], '{"description":"En Ruby no se declara el tipo: simplemente asignas un valor a un nombre.","code":"edad = 18\nnombre = \"Ana\"\nactivo = true"}'::jsonb, '{"description":"Los bloques if/else en Ruby se cierran con la palabra end.","code":"edad = 18\n\nif edad >= 18\n  puts \"Eres mayor de edad\"\nelse\n  puts \"Eres menor de edad\"\nend"}'::jsonb, '{"description":"times es una forma muy natural de repetir un bloque en Ruby.","code":"5.times do |i|\n  puts \"Vuelta número #{i}\"\nend"}'::jsonb, '[{"title":"Instala Ruby","description":"Descarga e instala Ruby desde su sitio oficial."},{"title":"Crea tu archivo","description":"Crea un archivo llamado hola.rb"},{"title":"Escribe tu primer programa","description":"Ruby permite interpolar variables dentro de los textos con #{}.","code":"nombre = \"Mundo\"\nputs \"¡Hola, #{nombre}!\""},{"title":"Ejecútalo","description":"Corre el archivo directamente con el intérprete de Ruby.","code":"ruby hola.rb"}]'::jsonb, '[{"title":"Guía rápida","platform":"ruby-lang.org","url":"https://www.ruby-lang.org/es/documentation/quickstart/"},{"title":"Cursos gratuitos","platform":"freeCodeCamp","url":"https://www.freecodecamp.org/learn"}]'::jsonb),
  ('typescript', 'TypeScript', 'JavaScript con superpoderes de tipado', '#3178C6', 2012, array['Anders Hejlsberg (Microsoft)']::text[], 'Multiparadigma: orientado a objetos y funcional, con tipado estático opcional', 'Microsoft presentó TypeScript en 2012 bajo la dirección de Anders Hejlsberg, el mismo creador de C#. Su idea era simple pero poderosa: agregar tipos estáticos opcionales a JavaScript para detectar errores antes de ejecutar el código, sin perder compatibilidad con el JavaScript ya existente. Hoy es el estándar de facto para proyectos grandes en frameworks como Angular, y muy popular en React y Node.js.', array['Tipado estático opcional sobre JavaScript', 'Detecta errores antes de ejecutar el código', 'Autocompletado e inteligencia de código muy superior en los editores', 'Compatible con cualquier código JavaScript existente']::text[], 'TypeScript no se ejecuta directamente: siempre se "transpila" (convierte) a JavaScript normal antes de correr en el navegador o en Node.js.', array['Aplicaciones web a gran escala', 'Frameworks como Angular y Next.js', 'Backend con Node.js más seguro', 'Librerías compartidas entre equipos']::text[], '{"description":"Igual que en JavaScript, pero puedes anotar el tipo explícitamente.","code":"let edad: number = 18;\nconst nombre: string = \"Ana\";\nlet activo: boolean = true;"}'::jsonb, '{"description":"if/else funciona igual que en JavaScript, con el beneficio del chequeo de tipos.","code":"let edad: number = 18;\n\nif (edad >= 18) {\n  console.log(\"Eres mayor de edad\");\n} else {\n  console.log(\"Eres menor de edad\");\n}"}'::jsonb, '{"description":"El bucle for repite un bloque de código un número determinado de veces.","code":"for (let i = 0; i < 5; i++) {\n  console.log(`Vuelta número ${i}`);\n}"}'::jsonb, '[{"title":"Instala TypeScript","description":"Con Node.js instalado, agrega TypeScript de forma global desde la terminal.","code":"npm install -g typescript"},{"title":"Crea tu archivo","description":"Crea un archivo llamado hola.ts"},{"title":"Escribe tu primer programa","description":"Declara el tipo de la variable de forma explícita.","code":"let nombre: string = \"Mundo\";\nconsole.log(`¡Hola, ${nombre}!`);"},{"title":"Compila y ejecuta","description":"TypeScript se traduce a JavaScript antes de ejecutarse con Node.","code":"tsc hola.ts\nnode hola.js"}]'::jsonb, '[{"title":"Documentación oficial","platform":"typescriptlang.org","url":"https://www.typescriptlang.org/docs/"},{"title":"Cursos gratuitos","platform":"freeCodeCamp","url":"https://www.freecodecamp.org/learn"}]'::jsonb),
  ('rust', 'Rust', 'Velocidad de C con seguridad de memoria', '#DE7C42', 2010, array['Graydon Hoare']::text[], 'Multiparadigma: concurrente, funcional y orientado a objetos', 'Graydon Hoare comenzó Rust como un proyecto personal en 2006, y Mozilla lo adoptó como proyecto oficial en 2009 para construir un motor de navegador más seguro. Su primera versión estable llegó en 2015. Su gran innovación es el "borrow checker", un sistema que garantiza seguridad de memoria sin necesidad de un recolector de basura, y por eso lo eligen empresas como Discord, Dropbox y hasta el kernel de Linux.', array['Seguridad de memoria garantizada en tiempo de compilación', 'Sin recolector de basura, pero sin fugas de memoria', 'Rendimiento comparable a C y C++', 'Manejo de errores explícito (Result y Option)']::text[], 'Rust ha sido votado como "el lenguaje más amado" en la encuesta anual de desarrolladores de Stack Overflow durante varios años consecutivos.', array['Sistemas y herramientas de línea de comandos', 'Motores de videojuegos', 'Programación de sistemas embebidos', 'Componentes críticos de rendimiento en apps grandes']::text[], '{"description":"Las variables son inmutables por defecto; usa mut para permitir que cambien.","code":"let edad = 18;\nlet nombre = \"Ana\";\nlet mut activo = true;"}'::jsonb, '{"description":"if/else en Rust no necesita paréntesis alrededor de la condición.","code":"let edad = 18;\n\nif edad >= 18 {\n    println!(\"Eres mayor de edad\");\n} else {\n    println!(\"Eres menor de edad\");\n}"}'::jsonb, '{"description":"for recorre un rango de valores de forma segura.","code":"for i in 0..5 {\n    println!(\"Vuelta número {}\", i);\n}"}'::jsonb, '[{"title":"Instala Rust","description":"Instala el toolchain de Rust usando rustup, el instalador oficial (rustup.rs)."},{"title":"Crea tu archivo","description":"Crea un archivo llamado hola.rs"},{"title":"Escribe tu primer programa","description":"El punto de entrada de todo programa en Rust es la función main.","code":"fn main() {\n    let nombre = \"Mundo\";\n    println!(\"¡Hola, {}!\", nombre);\n}"},{"title":"Compila y ejecuta","description":"Compila el archivo para generar un binario y luego ejecútalo.","code":"rustc hola.rs\n./hola"}]'::jsonb, '[{"title":"El libro de Rust","platform":"doc.rust-lang.org","url":"https://doc.rust-lang.org/book/"},{"title":"Cursos gratuitos","platform":"freeCodeCamp","url":"https://www.freecodecamp.org/learn"}]'::jsonb),
  ('dart', 'Dart', 'El lenguaje detrás de Flutter', '#0175C2', 2011, array['Lars Bak', 'Kasper Lund (Google)']::text[], 'Multiparadigma: orientado a objetos y funcional', 'Google presentó Dart en 2011 con la idea original de ofrecer una alternativa a JavaScript para el navegador. Esa apuesta inicial no despegó, pero el lenguaje encontró su verdadero propósito en 2017 al convertirse en el motor de Flutter, el framework de Google para crear apps multiplataforma. Hoy Dart vive prácticamente unido a Flutter.', array['Compila a código nativo (ARM, x64) o a JavaScript', '"Hot reload": ves los cambios de tu app al instante', 'Tipado sólido y seguro', 'Diseñado desde el inicio para interfaces de usuario']::text[], 'El nombre "Dart" no es un acrónimo: sus creadores buscaban un nombre corto, memorable y fácil de pronunciar en cualquier idioma.', array['Aplicaciones móviles con Flutter', 'Aplicaciones de escritorio multiplataforma', 'Aplicaciones web con Flutter Web', 'Scripts del lado del servidor']::text[], '{"description":"Dart tiene tipado sólido, aunque también permite inferencia con var.","code":"int edad = 18;\nString nombre = \"Ana\";\nbool activo = true;"}'::jsonb, '{"description":"if/else funciona de forma muy similar a Java o JavaScript.","code":"int edad = 18;\n\nif (edad >= 18) {\n  print(\"Eres mayor de edad\");\n} else {\n  print(\"Eres menor de edad\");\n}"}'::jsonb, '{"description":"El bucle for clásico repite un bloque un número determinado de veces.","code":"for (int i = 0; i < 5; i++) {\n  print(\"Vuelta número $i\");\n}"}'::jsonb, '[{"title":"Instala el SDK de Dart","description":"Instala el SDK de Dart, o instala Flutter, que ya lo incluye."},{"title":"Crea tu archivo","description":"Crea un archivo llamado hola.dart"},{"title":"Escribe tu primer programa","description":"El punto de entrada de todo programa en Dart es la función main.","code":"void main() {\n  String nombre = \"Mundo\";\n  print(\"¡Hola, $nombre!\");\n}"},{"title":"Ejecútalo","description":"Corre el archivo directamente con el comando dart.","code":"dart run hola.dart"}]'::jsonb, '[{"title":"Guías oficiales","platform":"dart.dev","url":"https://dart.dev/guides"},{"title":"Cursos gratuitos","platform":"freeCodeCamp","url":"https://www.freecodecamp.org/learn"}]'::jsonb),
  ('c', 'C', 'El padre de casi todos los lenguajes modernos', '#A8B9CC', 1972, array['Dennis Ritchie']::text[], 'Procedural', 'Dennis Ritchie creó C en los Laboratorios Bell en 1972 para reescribir el sistema operativo Unix, que hasta entonces estaba en ensamblador. Su combinación de control de bajo nivel con una sintaxis relativamente simple lo convirtió en la base de la que nacieron C++, Java, C#, JavaScript y muchos otros lenguajes. Más de 50 años después, sigue siendo esencial para sistemas operativos y software embebido.', array['Acceso directo a la memoria mediante punteros', 'Compila a código máquina muy eficiente', 'Sin recolector de basura: el programador administra la memoria', 'Estándar ISO que se sigue actualizando']::text[], 'El sistema operativo Unix, y por extensión Linux, están escritos casi por completo en C, lo que demuestra su vigencia más de 50 años después de su creación.', array['Sistemas operativos', 'Controladores de hardware (drivers)', 'Sistemas embebidos y microcontroladores', 'Bases del resto de lenguajes modernos']::text[], '{"description":"En C toda variable declara explícitamente su tipo y ocupa memoria fija.","code":"int edad = 18;\nchar nombre[] = \"Ana\";\nint activo = 1; // C clásico no tiene un tipo booleano nativo"}'::jsonb, '{"description":"if/else evalúa una expresión entre paréntesis; en C, 0 es falso y cualquier otro valor es verdadero.","code":"int edad = 18;\n\nif (edad >= 18) {\n    printf(\"Eres mayor de edad\\n\");\n} else {\n    printf(\"Eres menor de edad\\n\");\n}"}'::jsonb, '{"description":"El bucle for clásico repite un bloque un número determinado de veces.","code":"for (int i = 0; i < 5; i++) {\n    printf(\"Vuelta número %d\\n\", i);\n}"}'::jsonb, '[{"title":"Instala un compilador","description":"Instala gcc para poder compilar programas en C."},{"title":"Crea tu archivo","description":"Crea un archivo llamado hola.c"},{"title":"Escribe tu primer programa","description":"Incluye la librería estándar de entrada/salida y usa printf.","code":"#include <stdio.h>\n\nint main() {\n    char *nombre = \"Mundo\";\n    printf(\"¡Hola, %s!\\n\", nombre);\n    return 0;\n}"},{"title":"Compila y ejecuta","description":"Compila el archivo para generar un ejecutable y luego corre ese ejecutable.","code":"gcc hola.c -o hola\n./hola"}]'::jsonb, '[{"title":"Referencia oficial","platform":"cppreference.com","url":"https://en.cppreference.com/w/c"},{"title":"Cursos gratuitos","platform":"freeCodeCamp","url":"https://www.freecodecamp.org/learn"}]'::jsonb),
  ('perl', 'Perl', 'La navaja suiza de la programación', '#39457E', 1987, array['Larry Wall']::text[], 'Multiparadigma: procedural y orientado a objetos', 'El lingüista y programador Larry Wall creó Perl en 1987 mientras trabajaba como administrador de sistemas, buscando una herramienta más potente que las disponibles para procesar texto y generar reportes. Su manejo de expresiones regulares integrado en el propio lenguaje lo hizo extremadamente popular en los años 90 para scripts de administración y las primeras páginas web dinámicas (CGI).', array['Expresiones regulares integradas en la sintaxis del lenguaje', 'Muy flexible: hay "más de una forma de hacerlo" (TMTOWTDI)', 'Ideal para procesar archivos de texto grandes', 'CPAN: un repositorio de módulos con décadas de antigüedad']::text[], 'Larry Wall, su creador, también es lingüista, lo que explica por qué Perl toma tantas ideas prestadas de los idiomas humanos naturales.', array['Procesamiento y manipulación de texto', 'Administración de sistemas', 'Scripts CGI para la web', 'Bioinformática']::text[], '{"description":"Las variables en Perl se declaran con my y llevan un símbolo según su tipo ($ para escalares).","code":"my $edad = 18;\nmy $nombre = \"Ana\";\nmy $activo = 1;"}'::jsonb, '{"description":"if/else evalúa una condición entre paréntesis, similar a C.","code":"my $edad = 18;\n\nif ($edad >= 18) {\n    print \"Eres mayor de edad\\n\";\n} else {\n    print \"Eres menor de edad\\n\";\n}"}'::jsonb, '{"description":"El bucle for clásico repite un bloque un número determinado de veces.","code":"for (my $i = 0; $i < 5; $i++) {\n    print \"Vuelta número $i\\n\";\n}"}'::jsonb, '[{"title":"Instala Perl","description":"Perl ya viene instalado en la mayoría de sistemas Linux y macOS."},{"title":"Crea tu archivo","description":"Crea un archivo llamado hola.pl"},{"title":"Escribe tu primer programa","description":"Perl permite interpolar variables directamente dentro de los textos.","code":"my $nombre = \"Mundo\";\nprint \"¡Hola, $nombre!\\n\";"},{"title":"Ejecútalo","description":"Corre el archivo directamente con el intérprete de Perl.","code":"perl hola.pl"}]'::jsonb, '[{"title":"learn.perl.org","platform":"Perl Foundation","url":"https://learn.perl.org/"},{"title":"Cursos gratuitos","platform":"freeCodeCamp","url":"https://www.freecodecamp.org/learn"}]'::jsonb),
  ('scala', 'Scala', 'Programación orientada a objetos y funcional en la JVM', '#DC322F', 2004, array['Martin Odersky']::text[], 'Multiparadigma: orientado a objetos y funcional', 'El profesor Martin Odersky diseñó Scala, cuyo nombre significa "scalable language" (lenguaje escalable), y lo publicó en 2004 buscando unir lo mejor de la programación orientada a objetos con la programación funcional sobre la máquina virtual de Java. Empresas como Twitter y LinkedIn lo adoptaron para manejar sistemas de altísima concurrencia, y de él nació después el famoso framework Apache Spark.', array['Combina programación orientada a objetos y funcional', 'Compatible al 100% con librerías de Java', 'Sistema de tipos muy expresivo', 'Motor de Apache Spark para big data']::text[], 'El nombre Scala viene de "scalable language" (lenguaje escalable), porque fue diseñado para crecer con las necesidades de sus usuarios, desde scripts pequeños hasta sistemas enormes.', array['Procesamiento de grandes volúmenes de datos (Apache Spark)', 'Sistemas concurrentes y distribuidos', 'Backend empresarial sobre la JVM', 'Streaming de datos en tiempo real']::text[], '{"description":"Usa var para variables que cambian y val para valores que no cambian (lo más común).","code":"var edad = 18\nval nombre = \"Ana\"\nvar activo = true"}'::jsonb, '{"description":"if/else en Scala también puede usarse como una expresión que devuelve un valor.","code":"val edad = 18\n\nif (edad >= 18) {\n  println(\"Eres mayor de edad\")\n} else {\n  println(\"Eres menor de edad\")\n}"}'::jsonb, '{"description":"Un for con un rango recorre una secuencia de valores.","code":"for (i <- 0 until 5) {\n  println(s\"Vuelta número $i\")\n}"}'::jsonb, '[{"title":"Instala Scala","description":"Instala el JDK y luego Scala (o usa sbt, su herramienta de construcción)."},{"title":"Crea tu archivo","description":"Crea un archivo llamado hola.scala"},{"title":"Escribe tu primer programa","description":"Con las versiones modernas de Scala, un método marcado con @main es tu punto de entrada.","code":"@main def hola(): Unit = {\n  val nombre = \"Mundo\"\n  println(s\"¡Hola, $nombre!\")\n}"},{"title":"Ejecútalo","description":"Scala puede compilar y ejecutar el script en un solo paso.","code":"scala hola.scala"}]'::jsonb, '[{"title":"Documentación oficial","platform":"docs.scala-lang.org","url":"https://docs.scala-lang.org/"},{"title":"Cursos gratuitos","platform":"freeCodeCamp","url":"https://www.freecodecamp.org/learn"}]'::jsonb),
  ('lua', 'Lua', 'Pequeño, veloz y perfecto para incrustar', '#000080', 1993, array['Roberto Ierusalimschy', 'Waldemar Celes', 'Luiz Henrique de Figueiredo']::text[], 'Multiparadigma: procedural y orientado a objetos (basado en prototipos)', 'Un equipo de investigadores brasileños de la Pontificia Universidad Católica de Río de Janeiro creó Lua en 1993, buscando un lenguaje ligero y fácil de incrustar dentro de otras aplicaciones escritas en C. Su nombre significa "luna" en portugués. Gracias a su tamaño mínimo y velocidad, hoy es el lenguaje de scripting favorito de la industria de los videojuegos, usado en World of Warcraft y Roblox.', array['Intérprete extremadamente pequeño y rápido', 'Fácil de incrustar dentro de aplicaciones en C/C++', 'Solo tiene una estructura de datos: la tabla', 'Consume muy poca memoria']::text[], 'Los addons y modificaciones de World of Warcraft se escriben en Lua, lo que lo convirtió en uno de los lenguajes de scripting más usados en la industria de los videojuegos.', array['Scripting dentro de videojuegos', 'Modificaciones y addons (World of Warcraft, Roblox)', 'Sistemas embebidos', 'Configuración de aplicaciones (como Neovim)']::text[], '{"description":"local declara una variable visible solo dentro de su bloque.","code":"local edad = 18\nlocal nombre = \"Ana\"\nlocal activo = true"}'::jsonb, '{"description":"Los bloques if/else en Lua se cierran con la palabra end.","code":"local edad = 18\n\nif edad >= 18 then\n  print(\"Eres mayor de edad\")\nelse\n  print(\"Eres menor de edad\")\nend"}'::jsonb, '{"description":"El bucle for numérico recorre un rango de valores.","code":"for i = 0, 4 do\n  print(\"Vuelta número \" .. i)\nend"}'::jsonb, '[{"title":"Instala Lua","description":"Descarga e instala el intérprete de Lua desde lua.org."},{"title":"Crea tu archivo","description":"Crea un archivo llamado hola.lua"},{"title":"Escribe tu primer programa","description":"Concatena texto usando el operador de puntos ..","code":"local nombre = \"Mundo\"\nprint(\"¡Hola, \" .. nombre .. \"!\")"},{"title":"Ejecútalo","description":"Corre el archivo directamente con el intérprete de Lua.","code":"lua hola.lua"}]'::jsonb, '[{"title":"Manual de referencia","platform":"lua.org","url":"https://www.lua.org/manual/5.4/"},{"title":"Cursos gratuitos","platform":"freeCodeCamp","url":"https://www.freecodecamp.org/learn"}]'::jsonb),
  ('elixir', 'Elixir', 'Programación funcional para sistemas que nunca caen', '#4B275F', 2011, array['José Valim']::text[], 'Funcional y concurrente', 'El programador brasileño José Valim, quien trabajaba en el equipo de Ruby on Rails, creó Elixir en 2011 buscando resolver los problemas de escalabilidad y concurrencia de Ruby. Construyó el lenguaje sobre la máquina virtual de Erlang (BEAM), heredando su legendaria capacidad para crear sistemas distribuidos tolerantes a fallos. Discord y Pinterest usan Elixir para soportar millones de conexiones simultáneas.', array['Construido sobre la máquina virtual de Erlang (BEAM)', 'Tolerancia a fallos: los procesos se reinician solos si fallan', 'Concurrencia masiva con procesos muy ligeros', 'Framework web Phoenix para tiempo real']::text[], 'Discord usa Elixir para manejar millones de conexiones de voz y chat simultáneas gracias a la legendaria estabilidad de la máquina virtual de Erlang.', array['Sistemas de mensajería en tiempo real', 'APIs de alta concurrencia', 'Aplicaciones distribuidas y tolerantes a fallos', 'Internet de las cosas (IoT)']::text[], '{"description":"En Elixir los datos son inmutables: \"reasignar\" en realidad crea un nuevo valor.","code":"edad = 18\nnombre = \"Ana\"\nactivo = true"}'::jsonb, '{"description":"Los bloques if/else en Elixir se cierran con la palabra end.","code":"edad = 18\n\nif edad >= 18 do\n  IO.puts(\"Eres mayor de edad\")\nelse\n  IO.puts(\"Eres menor de edad\")\nend"}'::jsonb, '{"description":"Elixir no tiene bucles tradicionales: usa funciones como Enum.each sobre un rango.","code":"Enum.each(0..4, fn i ->\n  IO.puts(\"Vuelta número #{i}\")\nend)"}'::jsonb, '[{"title":"Instala Elixir","description":"Instala Elixir siguiendo la guía oficial (incluye la máquina virtual de Erlang)."},{"title":"Crea tu archivo","description":"Crea un archivo llamado hola.exs"},{"title":"Escribe tu primer programa","description":"Elixir permite interpolar variables dentro de los textos con #{}.","code":"nombre = \"Mundo\"\nIO.puts(\"¡Hola, #{nombre}!\")"},{"title":"Ejecútalo","description":"Los scripts de Elixir (.exs) se ejecutan directamente, sin compilar por separado.","code":"elixir hola.exs"}]'::jsonb, '[{"title":"Guía oficial","platform":"elixir-lang.org","url":"https://elixir-lang.org/getting-started/introduction.html"},{"title":"Cursos gratuitos","platform":"freeCodeCamp","url":"https://www.freecodecamp.org/learn"}]'::jsonb)
on conflict (id) do update set
  name = excluded.name, tagline = excluded.tagline, color = excluded.color, year = excluded.year,
  founders = excluded.founders, paradigm = excluded.paradigm, history = excluded.history,
  key_features = excluded.key_features, curiosity = excluded.curiosity, use_cases = excluded.use_cases,
  variables_example = excluded.variables_example, conditionals_example = excluded.conditionals_example,
  loops_example = excluded.loops_example, steps = excluded.steps, courses = excluded.courses;

insert into public.frameworks (id, name, language_id, tagline, description, year, creator, color, key_features, curiosity, use_cases, docs_url) values
  ('laravel', 'Laravel', 'php', 'El framework web más popular de PHP', 'Laravel es un framework para crear aplicaciones y APIs web con PHP, conocido por su sintaxis elegante y expresiva. Incluye herramientas listas para usar como un ORM (Eloquent), sistema de rutas, autenticación y migraciones de base de datos, lo que permite construir aplicaciones robustas mucho más rápido que con PHP puro.', 2011, 'Taylor Otwell', '#FF2D20', array['ORM Eloquent para trabajar con la base de datos como objetos', 'Sistema de migraciones para versionar la base de datos', 'Blade: su propio motor de plantillas', 'Artisan: una potente herramienta de línea de comandos']::text[], 'Taylor Otwell creó Laravel porque sentía que otros frameworks de PHP de la época no incluían funciones modernas como autenticación integrada.', array['Aplicaciones web', 'APIs REST', 'Comercio electrónico', 'Sistemas de gestión de contenido']::text[], 'https://laravel.com/docs'),
  ('django', 'Django', 'python', 'Un framework web "con las baterías incluidas"', 'Django es un framework web de alto nivel para Python que sigue la filosofía de "baterías incluidas": trae de fábrica un ORM, panel de administración automático, sistema de autenticación y protección contra vulnerabilidades comunes. Fue creado en la redacción de un periódico para publicar noticias a toda velocidad, y hoy es la base de plataformas como Instagram y Spotify.', 2005, 'Adrian Holovaty y Simon Willison', '#092E20', array['Panel de administración generado automáticamente', 'ORM propio para trabajar con la base de datos sin escribir SQL', 'Seguridad integrada contra ataques comunes (CSRF, inyección SQL)', 'Sigue el principio "no te repitas" (DRY)']::text[], 'Django lleva el nombre del guitarrista de jazz belga Django Reinhardt, uno de los músicos favoritos de uno de sus creadores.', array['Aplicaciones web robustas', 'APIs con Django REST Framework', 'Plataformas de contenido', 'Paneles administrativos']::text[], 'https://docs.djangoproject.com/'),
  ('flask', 'Flask', 'python', 'Un microframework minimalista para Python', 'Flask es un microframework para Python que da solo lo esencial para crear una aplicación web: rutas y manejo de peticiones. A diferencia de Django, no impone una estructura fija, por lo que es ideal para quienes quieren elegir sus propias herramientas y mantener el proyecto ligero.', 2010, 'Armin Ronacher', '#000000', array['Núcleo minimalista, extensible con paquetes opcionales', 'No impone una estructura de carpetas fija', 'Ideal para aprender cómo funciona un framework web por dentro', 'Basado en las librerías Werkzeug y Jinja2']::text[], 'Flask empezó como una broma del Día de los Inocentes en 2010, antes de convertirse en uno de los frameworks de Python más usados del mundo.', array['APIs REST pequeñas', 'Prototipos rápidos', 'Microservicios', 'Proyectos educativos']::text[], 'https://flask.palletsprojects.com/'),
  ('react', 'React', 'javascript', 'La biblioteca de interfaces más usada del mundo', 'React es una biblioteca de JavaScript para construir interfaces de usuario a partir de piezas reutilizables llamadas componentes. Introdujo el concepto de DOM virtual para actualizar la pantalla de forma eficiente y cambió la manera en que se construyen aplicaciones web modernas. Es también la base de React Native, con el que está hecha esta misma app.', 2013, 'Jordan Walke (Facebook)', '#61DAFB', array['DOM virtual para actualizar la pantalla de forma eficiente', 'Arquitectura basada en componentes reutilizables', 'Hooks para manejar estado y efectos secundarios', 'Enorme ecosistema de librerías compatibles']::text[], 'React se usó primero internamente en el feed de noticias de Facebook en 2011, y no se liberó como código abierto hasta 2013.', array['Interfaces web interactivas', 'Aplicaciones de una sola página (SPA)', 'Dashboards', 'Bases para React Native']::text[], 'https://react.dev/'),
  ('angular', 'Angular', 'typescript', 'Un framework completo para aplicaciones empresariales', 'Angular es un framework mantenido por Google, escrito en TypeScript, que ofrece todo lo necesario para construir aplicaciones grandes: enrutamiento, inyección de dependencias, formularios y herramientas de línea de comandos propias. Es la evolución completa de AngularJS (2010), reescrita desde cero en 2016.', 2016, 'Google', '#DD0031', array['Inyección de dependencias integrada', 'CLI oficial para generar y mantener proyectos', 'TypeScript de forma nativa en todo el framework', 'Enrutador y formularios reactivos incluidos']::text[], 'Angular (2+) fue una reescritura completa desde cero de AngularJS, tan distinta que en la práctica se consideran dos frameworks diferentes.', array['Aplicaciones empresariales grandes', 'Paneles administrativos complejos', 'Aplicaciones con equipos numerosos']::text[], 'https://angular.dev/'),
  ('vue', 'Vue.js', 'javascript', 'Un framework progresivo, fácil de adoptar poco a poco', 'Vue.js es un framework para construir interfaces de usuario que se puede integrar en un proyecto de forma gradual, desde una sola página hasta una aplicación completa. Evan You lo creó tras trabajar con Angular en Google, buscando quedarse con lo mejor de ese framework pero con una curva de aprendizaje mucho más suave.', 2014, 'Evan You', '#42B883', array['Curva de aprendizaje suave, ideal para principiantes', 'Reactividad automática de los datos', 'Se puede adoptar poco a poco en un proyecto existente', 'Documentación oficial considerada una de las mejores del ecosistema web']::text[], 'Evan You creó Vue tomando lo que más le gustaba de Angular tras trabajar en Google, pero eliminando lo que consideraba innecesariamente complejo.', array['Interfaces interactivas', 'Aplicaciones de una sola página (SPA)', 'Integración gradual en sitios existentes']::text[], 'https://vuejs.org/guide/introduction.html'),
  ('express', 'Express', 'javascript', 'El framework backend minimalista de Node.js', 'Express es un framework minimalista para crear servidores y APIs con Node.js. Ofrece un sistema simple de rutas y middlewares sin imponer una estructura estricta, lo que lo convirtió durante años en el estándar de facto para el backend en JavaScript.', 2010, 'TJ Holowaychuk', '#000000', array['Sistema de rutas y middlewares muy simple', 'Base de muchos otros frameworks de Node.js', 'Extremadamente ligero y rápido de configurar', 'Compatible con cualquier base de datos']::text[], 'Express es tan influyente que forma parte de los acrónimos "MEAN" y "MERN", dos de los stacks más populares para desarrollo web con JavaScript.', array['APIs REST', 'Servidores backend', 'Microservicios en Node.js']::text[], 'https://expressjs.com/'),
  ('nextjs', 'Next.js', 'javascript', 'React con renderizado en el servidor y mucho más', 'Next.js es un framework construido sobre React que añade renderizado en el servidor, generación de sitios estáticos, rutas basadas en archivos y optimización automática de imágenes. Simplifica muchas decisiones difíciles de configurar a mano en un proyecto de React puro.', 2016, 'Vercel (Guillermo Rauch)', '#000000', array['Renderizado en el servidor (SSR) y generación estática (SSG)', 'Sistema de rutas basado en archivos y carpetas', 'Optimización automática de imágenes y fuentes', 'API Routes para crear backend dentro del mismo proyecto']::text[], 'Empresas como TikTok, Twitch y Notion usan Next.js para sus sitios web de cara al público gracias a su velocidad de carga.', array['Sitios renderizados en el servidor', 'Tiendas en línea', 'Blogs y sitios de marketing', 'Aplicaciones full-stack']::text[], 'https://nextjs.org/docs'),
  ('spring', 'Spring', 'java', 'El framework empresarial más usado en Java', 'Spring es un framework para Java que simplifica el desarrollo de aplicaciones empresariales mediante la inyección de dependencias y una enorme cantidad de módulos (Spring Boot, Spring Security, etc.). Es la columna vertebral de miles de sistemas bancarios y corporativos en todo el mundo.', 2003, 'Rod Johnson', '#6DB33F', array['Inyección de dependencias como pilar central', 'Spring Boot elimina casi toda la configuración manual', 'Módulos para seguridad, datos y microservicios', 'Décadas de estabilidad en entornos empresariales']::text[], 'Spring nació como una reacción de Rod Johnson contra la complejidad excesiva de Enterprise JavaBeans (EJB), el estándar empresarial de Java de esa época.', array['Sistemas bancarios y financieros', 'Aplicaciones empresariales', 'Microservicios en Java']::text[], 'https://spring.io/projects/spring-framework'),
  ('rails', 'Ruby on Rails', 'ruby', 'El framework que popularizó el desarrollo web ultra rápido', 'Ruby on Rails es un framework web para Ruby que popularizó la idea de "convención sobre configuración": si sigues sus convenciones, puedes construir una aplicación funcional en muy poco tiempo. Su llegada en 2004 cambió la forma en que la industria pensaba la velocidad de desarrollo web.', 2004, 'David Heinemeier Hansson (DHH)', '#CC0000', array['Convención sobre configuración: menos decisiones, más productividad', 'ActiveRecord para trabajar con la base de datos como objetos', 'Generadores de código (scaffolding) para prototipar rápido', 'Comunidad muy orientada a buenas prácticas']::text[], 'Basecamp, la empresa de David Heinemeier Hansson, construyó Rails como una extracción del código que ya usaban internamente para su propio producto.', array['Aplicaciones web para startups', 'Prototipos y MVPs', 'Plataformas de comercio electrónico']::text[], 'https://guides.rubyonrails.org/'),
  ('aspnet', 'ASP.NET Core', 'csharp', 'El framework web moderno de Microsoft', 'ASP.NET Core es el framework de Microsoft para construir aplicaciones y APIs web con C#, rediseñado para ser multiplataforma (Windows, Linux y macOS) y de alto rendimiento. Es una pieza clave del ecosistema .NET para el desarrollo empresarial en la nube.', 2016, 'Microsoft', '#512BD4', array['Multiplataforma: corre en Windows, Linux y macOS', 'Alto rendimiento, uno de los frameworks web más rápidos que existen', 'Inyección de dependencias integrada de fábrica', 'Compatible con Blazor para crear interfaces web con C#']::text[], 'ASP.NET Core fue una reescritura total de Microsoft para dejar de depender exclusivamente de Windows, algo impensable en las primeras versiones de .NET.', array['Aplicaciones empresariales', 'APIs web', 'Aplicaciones en la nube con Azure']::text[], 'https://learn.microsoft.com/aspnet/core'),
  ('flutter', 'Flutter', 'dart', 'Una sola base de código para móvil, web y escritorio', 'Flutter es el framework de Google para crear aplicaciones nativas de iOS, Android, web y escritorio desde una única base de código en Dart. Dibuja cada píxel de su propia interfaz en lugar de usar los componentes nativos del sistema, lo que le da un control visual y de rendimiento muy preciso.', 2017, 'Google', '#02569B', array['Dibuja su propia interfaz en lugar de usar componentes nativos', '"Hot reload" para ver cambios de diseño al instante', 'Un solo código para iOS, Android, web y escritorio', 'Widgets personalizables hasta el último detalle']::text[], 'Flutter usa el motor gráfico Skia, el mismo que dibuja los píxeles de Google Chrome y Android, lo que explica su rendimiento visual tan fluido.', array['Apps móviles multiplataforma', 'Aplicaciones de escritorio', 'Prototipos con interfaces muy personalizadas']::text[], 'https://docs.flutter.dev/'),
  ('react-native', 'React Native', 'javascript', 'Apps móviles nativas usando React', 'React Native permite construir aplicaciones móviles nativas para iOS y Android usando React y JavaScript, compartiendo una sola base de código entre ambas plataformas. Esta misma aplicación que estás usando está hecha con React Native y Expo.', 2015, 'Facebook (Meta)', '#61DAFB', array['Comparte una sola base de código entre iOS y Android', 'Usa componentes nativos reales (no WebView)', 'Compatible con Expo para simplificar la configuración', 'Enorme reutilización de conocimiento con React']::text[], 'Aplicaciones muy conocidas como Instagram y Discord usan (o han usado) React Native en partes de su interfaz.', array['Apps para iOS y Android', 'Prototipos móviles rápidos', 'Aplicaciones multiplataforma con Expo']::text[], 'https://reactnative.dev/docs/getting-started'),
  ('symfony', 'Symfony', 'php', 'Componentes reutilizables para PHP profesional', 'Symfony es un conjunto de componentes PHP reutilizables y un framework web robusto pensado para aplicaciones grandes y de larga duración. Es especialmente relevante porque varios de sus componentes son la base sobre la que está construido Laravel.', 2005, 'Fabien Potencier (SensioLabs)', '#000000', array['Componentes que se pueden usar de forma independiente', 'Muy configurable para proyectos de larga duración', 'Sigue de cerca los estándares PSR de PHP', 'Base de otros proyectos como Laravel y Drupal']::text[], 'Varios componentes internos de Laravel, como el manejo de rutas y de consola, están construidos directamente sobre componentes de Symfony.', array['Aplicaciones empresariales complejas', 'Sistemas de larga duración', 'Componentes reutilizables para otros frameworks']::text[], 'https://symfony.com/doc/current/index.html'),
  ('gin', 'Gin', 'go', 'Un framework web ligero y veloz para Go', 'Gin es un framework minimalista para construir APIs web en Go, apreciado por su altísimo rendimiento y su API sencilla basada en middlewares. Es una de las opciones más populares cuando se necesita velocidad extrema en el backend.', 2014, 'Manu Martínez-Almeida', '#00ADD8', array['Hasta 40 veces más rápido que otros routers de Go según sus benchmarks', 'API minimalista basada en middlewares', 'Validación de datos de entrada integrada', 'Muy popular para microservicios en contenedores']::text[], 'El nombre "Gin" (ginebra) sigue la tradición de Go de usar nombres cortos y sencillos, jugando con la idea de un framework tan "ligero" como la bebida.', array['APIs REST de alto rendimiento', 'Microservicios en Go']::text[], 'https://gin-gonic.com/docs/'),
  ('vapor', 'Vapor', 'swift', 'Servidores y APIs escritos en Swift', 'Vapor es un framework que permite usar Swift, el lenguaje de las apps de Apple, también en el backend. Con Vapor, un mismo equipo puede compartir lógica y tipos entre la app de iOS y el servidor que la alimenta.', 2016, 'Tanner Nelson y la comunidad Vapor', '#0D0D0D', array['Basado en SwiftNIO, la librería de red asíncrona de Apple', 'Comparte modelos de datos con apps iOS escritas en Swift', 'ORM propio llamado Fluent', 'Comunidad activa dentro del ecosistema Swift']::text[], 'Vapor permite que un mismo desarrollador escriba tanto la app de iOS como el servidor que la alimenta, sin cambiar de lenguaje de programación.', array['APIs backend para apps de Apple', 'Servidores web en Swift']::text[], 'https://docs.vapor.codes/'),
  ('rocket', 'Rocket', 'rust', 'Un framework web seguro y fácil de usar para Rust', 'Rocket es un framework web para Rust enfocado en la seguridad de tipos, la velocidad y una experiencia de desarrollo agradable, algo poco común en el mundo de Rust. Aprovecha el sistema de tipos del lenguaje para prevenir errores comunes en tiempo de compilación.', 2016, 'Sergio Benitez', '#D33847', array['Verificación de tipos en tiempo de compilación para las rutas', 'Manejo de errores explícito heredado de Rust', 'Enfocado en la experiencia de desarrollo (developer experience)', 'Guardas de solicitud (request guards) para validar peticiones']::text[], 'Rocket popularizó dentro de la comunidad Rust la idea de que un framework web podía ser tan seguro como el propio lenguaje, sin sacrificar comodidad.', array['APIs web seguras', 'Backends de alto rendimiento']::text[], 'https://rocket.rs/guide/v0.5/')
on conflict (id) do update set
  name = excluded.name, language_id = excluded.language_id, tagline = excluded.tagline,
  description = excluded.description, year = excluded.year, creator = excluded.creator, color = excluded.color,
  key_features = excluded.key_features, curiosity = excluded.curiosity, use_cases = excluded.use_cases,
  docs_url = excluded.docs_url;
